package vn.covie.checkout.model;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; import com.fasterxml.jackson.databind.JsonNode; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="checkout_sessions") public class CheckoutSessionEntity{@Id private UUID id;@Column(name="token_hash",nullable=false,length=64,unique=true)private String tokenHash;@Column(name="user_id",nullable=false)private UUID userId;@Enumerated(EnumType.STRING)@Column(name="source_type",nullable=false)private CheckoutSourceType sourceType;@JdbcTypeCode(SqlTypes.JSON)@Column(name="source_context",nullable=false,columnDefinition="jsonb")private JsonNode sourceContext;@Column(name="cart_version")private Long cartVersion;@JdbcTypeCode(SqlTypes.JSON)@Column(name="request_snapshot",nullable=false,columnDefinition="jsonb")private JsonNode requestSnapshot;@JdbcTypeCode(SqlTypes.JSON)@Column(name="preview_snapshot",nullable=false,columnDefinition="jsonb")private JsonNode previewSnapshot;@Column(name="expires_at",nullable=false)private Instant expiresAt;@Column(name="consumed_at")private Instant consumedAt;@Column(name="created_at",nullable=false)private Instant createdAt;protected CheckoutSessionEntity(){}public static CheckoutSessionEntity create(UUID id,String hash,UUID user,CheckoutSourceType type,JsonNode source,Long cartVersion,JsonNode request,JsonNode preview,Instant expires,Instant now){CheckoutSessionEntity s=new CheckoutSessionEntity();s.id=id;s.tokenHash=hash;s.userId=user;s.sourceType=type;s.sourceContext=source;s.cartVersion=cartVersion;s.requestSnapshot=request;s.previewSnapshot=preview;s.expiresAt=expires;s.createdAt=now;return s;}public void consume(Instant now){consumedAt=now;}public UUID getId(){return id;}public String getTokenHash(){return tokenHash;}public UUID getUserId(){return userId;}public CheckoutSourceType getSourceType(){return sourceType;}public JsonNode getSourceContext(){return sourceContext;}public Long getCartVersion(){return cartVersion;}public JsonNode getRequestSnapshot(){return requestSnapshot;}public JsonNode getPreviewSnapshot(){return previewSnapshot;}public Instant getExpiresAt(){return expiresAt;}public Instant getConsumedAt(){return consumedAt;}}
